/**
 * Nexora Academy client application.
 *
 * Route snapshots are stored above in this same editable app.js file.
 * Media files remain in assets/.
 */
(function () {
  'use strict';

  // ---------------------------------------------------------------------------
  // Runtime foundations
  // ---------------------------------------------------------------------------

  const PAGES = globalThis.__NEXORA_PAGES__;
  const DEFAULT_ROUTE = 'home';

  if (!PAGES || !PAGES[DEFAULT_ROUTE]) {
    throw new Error('Nexora page data did not load.');
  }

  const $ = (selector, root = document) => root.querySelector(selector);

  const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));

  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));

  let pageController = null;

  // ---------------------------------------------------------------------------
  // Routing and rendering
  // ---------------------------------------------------------------------------

  function parseBodyAttributes(raw) {
    const attrs = {};
    String(raw || '').replace(/([\w:-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g, (_, name, dq, sq, bare) => {
      attrs[name.toLowerCase()] = dq ?? sq ?? bare ?? '';
      return '';
    });
    return attrs;
  }

  function injectAssets(html) {
    return html.replace(/__NAIC_ASSET__(.+?)__/g, (_, key) => `assets/${key}`);
  }

  function routeFromHash() {
    const hash = location.hash || '';
    const match = hash.match(/^#\/nav\/([^?]+)(?:\?(.*))?$/);
    if (!match)
      return { route: DEFAULT_ROUTE, target: '' };
    const route = decodeURIComponent(match[1]);
    const params = new URLSearchParams(match[2] || '');
    return { route: PAGES[route] ? route : DEFAULT_ROUTE, target: params.get('target') || '' };
  }

  function setMeta(meta) {
    document.title = meta.title || 'Nexora Academy';
    const desc = document.querySelector('meta[name="description"]');
    const keywords = document.querySelector('meta[name="keywords"]');
    if (desc)
      desc.content = meta.description || '';
    if (keywords)
      keywords.content = meta.keywords || '';
  }

  function renderRoute({ route, target = '' }, options = {}) {
    const page = PAGES[route] || PAGES[DEFAULT_ROUTE];
    pageController?.abort();
    pageController = new AbortController();
    const signal = pageController.signal;
    const attrs = parseBodyAttributes(page.bodyAttrs);
    document.body.className = attrs.class || '__variable_7fc4d2 antialiased';
    document.body.setAttribute('style', attrs.style || 'overflow:auto');
    document.body.dataset.page = route;
    document.body.innerHTML = injectAssets(page.html);
    setMeta(page.meta);
    initPage(signal);
    const finishPosition = () => {
      if (target) {
        const node = document.getElementById(target);
        if (node) {
          node.scrollIntoView({ block: 'center' });
          node.classList.remove('naic-target-flash');
          requestAnimationFrame(() => node.classList.add('naic-target-flash'));
          return;
        }
      }
      if (!options.keepScroll)
        window.scrollTo(0, 0);
    };
    requestAnimationFrame(() => requestAnimationFrame(finishPosition));
  }

  function navigate(route, target = '') {
    const next = `#/nav/${encodeURIComponent(route)}${target ? `?target=${encodeURIComponent(target)}` : ''}`;
    if (location.hash === next)
      renderRoute({ route, target });
    else
      location.hash = next;
  }

  // ---------------------------------------------------------------------------
  // Shared form utilities
  // ---------------------------------------------------------------------------

  function announce(form, message, state = 'success') {
    let node = $('.naic-form-message', form);
    if (!node) {
      node = document.createElement('p');
      node.className = 'naic-form-message';
      node.setAttribute('role', 'status');
      node.setAttribute('aria-live', 'polite');
      form.appendChild(node);
    }
    node.dataset.state = state;
    node.textContent = message;
  }

  function clearInvalid(form) {
    $$('.naic-field-invalid', form).forEach((field) => field.classList.remove('naic-field-invalid'));
  }

  function markInvalid(field) {
    if (!field)
      return;
    field.classList.add('naic-field-invalid');
    field.addEventListener('input', () => field.classList.remove('naic-field-invalid'), { once: true });
  }

  function validEmail(value) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || '').trim());
  }

  function safeStoredValue(value) {
    if (value instanceof File)
      return { name: value.name, size: value.size, type: value.type };
    return value;
  }

  function saveOffline(kind, form) {
    const key = `naic_${kind}_submissions`;
    let current = [];
    try {
      current = JSON.parse(localStorage.getItem(key) || '[]');
    }
    catch (_) {
      current = [];
    }
    const data = {};
    for (const [name, value] of new FormData(form).entries())
      data[name] = safeStoredValue(value);
    current.push({ ...data, stored_at: new Date().toISOString() });
    localStorage.setItem(key, JSON.stringify(current));
    return { ok: true, offline: true };
  }

  // ---------------------------------------------------------------------------
  // Page behavior modules
  // ---------------------------------------------------------------------------

  function initHeader(signal) {
    const header = $('.Header_header__8yaFd');
    if (header) {
      const update = () => header.classList.toggle('Header_fixed__CRpV_', window.scrollY > 12);
      update();
      window.addEventListener('scroll', update, { passive: true, signal });
    }
    const mobileMenu = $('.HeaderMobile_header_mobile_menu__b38W_');
    const menuButtons = $$('.header__menu__btn');
    if (mobileMenu && menuButtons.length) {
      const open = () => {
        mobileMenu.classList.add('HeaderMobile_show__tPAoO');
        document.documentElement.classList.add('naic-menu-open');
        document.body.classList.add('naic-menu-open');
        menuButtons[0]?.setAttribute('aria-expanded', 'true');
      };
      const close = () => {
        mobileMenu.classList.remove('HeaderMobile_show__tPAoO');
        document.documentElement.classList.remove('naic-menu-open');
        document.body.classList.remove('naic-menu-open');
        menuButtons[0]?.setAttribute('aria-expanded', 'false');
      };
      menuButtons[0]?.setAttribute('aria-label', 'Open menu');
      menuButtons[0]?.setAttribute('aria-expanded', 'false');
      menuButtons[0]?.addEventListener('click', open, { signal });
      menuButtons[1]?.setAttribute('aria-label', 'Close menu');
      menuButtons[1]?.addEventListener('click', close, { signal });
      $$('a', mobileMenu).forEach((a) => a.addEventListener('click', close, { signal }));
      document.addEventListener('keydown', (event) => { if (event.key === 'Escape')
        close(); }, { signal });
    }
    $$('.HeaderMobile_menu__accordion__item__lNOEz[type="button"]').forEach((button) => {
      const body = $('[class*="menu__accordion__item__body"]', button);
      if (!body)
        return;
      button.setAttribute('aria-expanded', 'false');
      body.hidden = true;
      button.addEventListener('click', () => {
        const expanded = button.getAttribute('aria-expanded') === 'true';
        button.setAttribute('aria-expanded', String(!expanded));
        body.hidden = expanded;
      }, { signal });
    });
  }

  function initHeroMedia(signal) {
    const video = $('.HeroSection_video__GVdk5');
    const playButton = $('button[aria-label="play / pause"]');
    const muteButton = $('button[aria-label="mute / unmute"]');
    const hasSource = Boolean(video?.querySelector('source[src]') || video?.getAttribute('src'));
    if (!video || !hasSource) {
      playButton?.setAttribute('aria-disabled', 'true');
      muteButton?.setAttribute('aria-disabled', 'true');
      return;
    }
    playButton?.addEventListener('click', async () => {
      try {
        if (video.paused)
          await video.play();
        else
          video.pause();
      }
      catch (_) {
        playButton.setAttribute('aria-disabled', 'true');
      }
    }, { signal });
    muteButton?.addEventListener('click', () => { video.muted = !video.muted; }, { signal });
  }

  // NEXORA EXACT HERO TYPEWRITER START
  function initNexoraHeroTypewriter(signal) {
    if (document.body.dataset.page !== 'home')
      return;

    const title = $('.HeroSection_content__title__Wr5gI');
    if (!title)
      return;

    const parts = $$(':scope > span', title);
    const exactText = 'Nexora Academy — Practical technology education';
    const originalParts = parts.map((part) => part.textContent.replace(/\s+/g, ' ').trim());

    if (parts.length !== 2 || originalParts.join(' ') !== exactText)
      return;

    title.setAttribute('aria-label', exactText);

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches)
      return;

    const characters = originalParts.map((part) => Array.from(part));

    parts.forEach((part) => {
      part.textContent = '';
      part.setAttribute('aria-hidden', 'true');
    });
    title.classList.add('naic-hero-typewriter-active');

    const pause = (milliseconds) => new Promise((resolve) => {
      if (signal.aborted) {
        resolve(false);
        return;
      }

      let settled = false;
      const finish = (completed) => {
        if (settled)
          return;
        settled = true;
        signal.removeEventListener('abort', cancel);
        resolve(completed);
      };
      const timer = window.setTimeout(() => finish(true), milliseconds);
      const cancel = () => {
        window.clearTimeout(timer);
        finish(false);
      };
      signal.addEventListener('abort', cancel, { once: true });
    });

    (async () => {
      if (!(await pause(250)))
        return;

      while (!signal.aborted) {
        // Forward typing.
        for (let partIndex = 0; partIndex < characters.length; partIndex += 1) {
          for (const character of characters[partIndex]) {
            if (signal.aborted)
              return;
            parts[partIndex].textContent += character;
            if (!(await pause(character === ' ' ? 28 : 54)))
              return;
          }
          if (partIndex === 0 && !(await pause(120)))
            return;
        }

        // Hold the completed sentence briefly, then delete it in exact reverse.
        if (!(await pause(1050)))
          return;

        for (let partIndex = characters.length - 1; partIndex >= 0; partIndex -= 1) {
          while (parts[partIndex].textContent.length > 0) {
            if (signal.aborted)
              return;
            parts[partIndex].textContent = Array.from(parts[partIndex].textContent).slice(0, -1).join('');
            if (!(await pause(32)))
              return;
          }
          if (partIndex > 0 && !(await pause(90)))
            return;
        }

        // Empty-state pause before the next forward pass.
        if (!(await pause(420)))
          return;
      }
    })();
  }
  // NEXORA EXACT HERO TYPEWRITER END

  function initApplicationForm(signal) {
    const form = $('#applicationForm');
    if (!form)
      return;
    form.noValidate = true;
    const steps = $$('[class*="ai-form__step_"]', form).filter((el) => el.className.includes('SendApplicationSection_ai-form__step___'));
    if (steps.length < 2)
      return;
    const activeClass = 'SendApplicationSection_active__5RPzX';
    const next = $('.ai-form__step__btn-next', form);
    const back = steps[1].querySelector('button[type="button"]');
    const showStep = (index) => {
      steps.forEach((step, i) => step.classList.toggle(activeClass, i === index));
      steps[index]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    };
    next?.addEventListener('click', () => {
      const selected = $('input[name="applicationType"]:checked', form);
      if (!selected) {
        announce(form, 'Select a request purpose to continue.', 'error');
        return;
      }
      announce(form, '', 'success');
      showStep(1);
    }, { signal });
    back?.addEventListener('click', () => showStep(0), { signal });
    const file = $('input[name="cv"]', form);
    const fileLabel = file ? $(`label[for="${file.id}"] [class*="label__text"]`, form) : null;
    file?.addEventListener('change', () => {
      if (file.files?.[0] && fileLabel)
        fileLabel.textContent = file.files[0].name;
    }, { signal });
    form.addEventListener('submit', (event) => {
      event.preventDefault();
      clearInvalid(form);
      const type = $('input[name="applicationType"]:checked', form);
      const fullname = $('input[name="fullname"]', form);
      const email = $('input[name="email"]', form);
      const phone = $('input[name="phone"]', form);
      const letter = $('[name="letter"]', form);
      const cv = $('input[name="cv"]', form);
      const invalid = [];
      if (!type)
        invalid.push(...$$('input[name="applicationType"]', form));
      if (!fullname?.value.trim())
        invalid.push(fullname);
      if (!email?.value || !validEmail(email.value))
        invalid.push(email);
      if (!phone?.value.trim())
        invalid.push(phone);
      if (!letter?.value.trim() || letter.value.trim().length < 50 || letter.value.length > 2000)
        invalid.push(letter);
      const selectedFile = cv?.files?.[0];
      if (!selectedFile || selectedFile.size > 10 * 1024 * 1024 || !/\.(pdf|doc|docx)$/i.test(selectedFile.name))
        invalid.push(cv);
      invalid.filter(Boolean).forEach(markInvalid);
      if (invalid.length) {
        announce(form, 'Check the information: complete every field, use a valid email address, write at least 50 characters, and attach a PDF or Word file smaller than 10 MB.', 'error');
        return;
      }
      const submit = $('button[type="submit"]', form);
      submit?.setAttribute('disabled', 'disabled');
      try {
        saveOffline('application', form);
        announce(form, 'The request was saved on this device.', 'success');
        form.reset();
        if (fileLabel)
          fileLabel.textContent = 'Attach supporting file';
        setTimeout(() => showStep(0), 500);
      }
      catch (_) {
        announce(form, 'The request could not be saved in browser storage.', 'error');
      }
      finally {
        submit?.removeAttribute('disabled');
      }
    }, { signal });
  }

  function initSimpleForms(signal) {
    $$('form[data-form-kind]').forEach((form) => {
      form.noValidate = true;
      form.addEventListener('submit', (event) => {
        event.preventDefault();
        clearInvalid(form);
        const kind = form.dataset.formKind;
        const invalid = [];
        if (kind === 'subscribe') {
          const email = $('input[name="email"]', form);
          if (!email?.value || !validEmail(email.value))
            invalid.push(email);
        }
        else {
          $$('[required]', form).forEach((field) => { if (!field.value?.trim())
            invalid.push(field); });
          const email = $('input[name="email"]', form);
          if (email && !validEmail(email.value))
            invalid.push(email);
          const letter = $('[name="letter"]', form);
          if (letter && letter.value.trim().length < 10)
            invalid.push(letter);
        }
        invalid.filter(Boolean).forEach(markInvalid);
        if (invalid.length) {
          announce(form, kind === 'subscribe' ? 'Enter a valid email address.' : 'Complete all required fields correctly.', 'error');
          return;
        }
        const submit = $('button[type="submit"]', form);
        submit?.setAttribute('disabled', 'disabled');
        try {
          saveOffline(kind, form);
          announce(form, kind === 'subscribe' ? 'The email was saved on this device.' : 'The request was saved on this device.', 'success');
          form.reset();
        }
        catch (_) {
          announce(form, 'The information could not be saved in browser storage.', 'error');
        }
        finally {
          submit?.removeAttribute('disabled');
        }
      }, { signal });
    });
  }

  function initVacancies(signal) {
    const input = $('#searchVacancies');
    const cards = $$('.Vacancies_ai-vacancies__item__MWNY2');
    if (!input || !cards.length)
      return;
    const tabs = $$('.Vacancies_ai-tabs__item__l5MN4');
    const activeClass = 'Vacancies_ai-tabs__item--active__dqm_Y';
    const filter = () => {
      const query = input.value.trim().toLocaleLowerCase('en');
      cards.forEach((card) => { card.hidden = !card.textContent.toLocaleLowerCase('en').includes(query); });
    };
    input.addEventListener('input', filter, { signal });
    tabs.forEach((tab) => tab.addEventListener('click', () => {
      tabs.forEach((x) => x.classList.remove(activeClass));
      tab.classList.add(activeClass);
      filter();
    }, { signal }));
  }

  function setupCoverflow({ containerSelector, prevSelector, nextSelector, depth = 220 }, signal) {
    const container = $(containerSelector);
    if (!container)
      return;
    const wrapper = $('.swiper-wrapper', container);
    const slides = $$('.swiper-slide', container);
    if (!wrapper || !slides.length)
      return;
    let active = Math.max(0, slides.findIndex((slide) => slide.classList.contains('swiper-slide-active')));
    const render = (animate = true) => {
      const containerWidth = container.clientWidth || window.innerWidth;
      const slideWidth = slides[active]?.getBoundingClientRect().width || 315;
      const margin = parseFloat(getComputedStyle(slides[active]).marginRight) || 0;
      const offset = containerWidth / 2 - slideWidth / 2 - active * (slideWidth + margin);
      wrapper.style.transition = animate ? 'transform 480ms ease' : 'none';
      wrapper.style.transform = `translate3d(${offset}px, 0, 0)`;
      slides.forEach((slide, index) => {
        const distance = index - active;
        slide.classList.toggle('swiper-slide-active', distance === 0);
        slide.classList.toggle('swiper-slide-prev', distance === -1);
        slide.classList.toggle('swiper-slide-next', distance === 1);
        slide.classList.toggle('swiper-slide-visible', Math.abs(distance) <= 2);
        slide.style.transition = animate ? 'transform 480ms ease, opacity 480ms ease' : 'none';
        slide.style.transform = `translate3d(${distance * -10}px, 0, ${-Math.abs(distance) * depth}px) scale(1)`;
        slide.style.zIndex = String(slides.length - Math.abs(distance));
        slide.style.opacity = Math.abs(distance) > 3 ? '0.25' : distance === 0 ? '1' : '0.55';
      });
    };
    const move = (delta) => { active = (active + delta + slides.length) % slides.length; render(true); };
    $(prevSelector)?.addEventListener('click', () => move(-1), { signal });
    $(nextSelector)?.addEventListener('click', () => move(1), { signal });
    let startX = null;
    container.addEventListener('pointerdown', (event) => { startX = event.clientX; container.setPointerCapture?.(event.pointerId); }, { signal });
    container.addEventListener('pointerup', (event) => {
      if (startX === null)
        return;
      const delta = event.clientX - startX;
      if (Math.abs(delta) > 45)
        move(delta > 0 ? -1 : 1);
      startX = null;
    }, { signal });
    window.addEventListener('resize', () => render(false), { signal });
    requestAnimationFrame(() => render(false));
  }

  function initSliders(signal) {
    setupCoverflow({
      containerSelector: '.SuccessStories_ai-success--stories__vv5bs .swiper',
      prevSelector: '.SuccessStories_section__header__controller__prev__aQ8hL',
      nextSelector: '.SuccessStories_section__header__controller__next__A3AXv',
      depth: 290,
    }, signal);
    setupCoverflow({
      containerSelector: '.ViewsFromNaic_ai-views--from--naic__Zd_6I .swiper',
      prevSelector: '.ViewsFromNaic_section__header__controller__prev__cyPxK',
      nextSelector: '.ViewsFromNaic_section__header__controller__next__wERDV',
      depth: 125,
    }, signal);
  }

  function initPagination(signal) {
    const buttons = $$('.Pagination_ai-pagination__item___y0si');
    if (!buttons.length)
      return;
    const pageButtons = buttons.filter((button) => /^\d+$/.test(button.textContent.trim()));
    const prev = buttons.find((button) => button.getAttribute('aria-label')?.includes('Previous'));
    const next = buttons.find((button) => button.getAttribute('aria-label')?.includes('Next'));
    let active = Math.max(0, pageButtons.findIndex((b) => b.classList.contains('Pagination_active__qQWfE')));
    const activeClass = 'Pagination_active__qQWfE';
    const setPage = (index) => {
      active = clamp(index, 0, pageButtons.length - 1);
      pageButtons.forEach((button, i) => {
        button.classList.toggle(activeClass, i === active);
        if (i === active)
          button.setAttribute('aria-current', 'page');
        else
          button.removeAttribute('aria-current');
      });
      const section = pageButtons[0]?.closest('section') || pageButtons[0]?.parentElement;
      section?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };
    pageButtons.forEach((button, i) => button.addEventListener('click', () => setPage(i), { signal }));
    prev?.addEventListener('click', () => setPage(active - 1), { signal });
    next?.addEventListener('click', () => setPage(active + 1), { signal });
  }

  function initPhoneInputs(signal) {
    $$('input[name="phone"]').forEach((input) => {
      input.setAttribute('inputmode', 'tel');
      input.setAttribute('autocomplete', 'tel');
      input.addEventListener('input', () => {
        input.value = input.value.replace(/[^0-9+()\-\s]/g, '').slice(0, 25);
      }, { signal });
    });
  }

  function initPage(signal) {
    initHeader(signal);
    initHeroMedia(signal);
    initNexoraHeroTypewriter(signal);
    initApplicationForm(signal);
    initSimpleForms(signal);
    initVacancies(signal);
    initSliders(signal);
    initPagination(signal);
    initPhoneInputs(signal);
  }

  // ---------------------------------------------------------------------------
  // Application bootstrap
  // ---------------------------------------------------------------------------

  document.addEventListener('click', (event) => {
    const link = event.target.closest('a[href^="#/nav/"]');
    if (!link || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)
      return;
    event.preventDefault();
    const href = link.getAttribute('href');
    if (location.hash === href)
      renderRoute(routeFromHash());
    else
      location.hash = href.slice(1);
  });

  window.addEventListener('hashchange', () => renderRoute(routeFromHash()));

  const boot = () => {
    if (!location.hash.match(/^#\/nav\//)) {
      history.replaceState(null, '', `${location.pathname}${location.search}#/nav/home`);
    }
    renderRoute(routeFromHash());
  };

  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  else
    boot();

})();
